<?php
/** Proof — deposits (spec "Proof", 5). */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ar_fixture();
$D = mk_customer('SMOKE Deposit Customer');
$mkr = function (string $amount, array $extra = []) use ($bea, $D): int { [$c, $b] = act($bea, '/receipts/save.php', ['customer' => $D, 'amount' => $amount, 'method' => 'cheque', 'reference' => 'DEP-' . $amount] + $extra); return (int) $b['record_id']; };
$bal = fn (string $code) => balance_of($code);
echo "1. A draft\n";
$r1 = $mkr('300.00'); $r2 = $mkr('450.00'); $r3 = $mkr('100.00', ['deposit_to' => $fx['bank']]);
$since = last_activity_id();
[$c, $b] = act($bea, '/deposits/save.php', ['bank_account' => $fx['bank'], 'deposit_date' => '2026-06-05', 'memo' => 'SMOKE Friday', 'receipts' => [$r1, $r2]]);
$d = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $d > 0 && ($b['location'] ?? '') === '/deposits/' . $d . '?notice=saved', "deposit_draft: 200, record_id $d");
$row = q('SELECT * FROM deposits WHERE id = :d', ['d' => $d])[0];
ok(preg_match('/^DEP-\d{6}$/', $row['number']) === 1 && $row['status'] === 'draft' && $row['total'] === '750.00' && $row['currency'] === 'USD', 'numbered at creation, a draft, the total is the receipts\' (750.00)');
$log = activity('deposit.draft', $since);
ok(count($log) === 1 && (int) $log[0]['bank_account_id'] === $fx['bank'] && str_contains((string) $log[0]['after'], '"receipts": 2'), 'deposit.draft logged with bank_account_id and the receipts count');
[$c, $b] = act($bea, '/deposits/add.php', ['deposit' => $d, 'receipt' => $r3]);
ok($c === 422 && str_contains(msg($b), 'only undeposited receipts join a deposit'), 'a bank receipt is refused: "… only undeposited receipts join a deposit"');
$r4 = $mkr('50.00');
[$c, $b] = act($bea, '/deposits/add.php', ['deposit' => $d, 'receipt' => $r4]);
ok($c === 200 && (string) one('SELECT total FROM deposits WHERE id = :d', ['d' => $d]) === '800.00', 'deposit_add_receipt: the total is 800.00');
[$c, $b] = act($bea, '/deposits/remove.php', ['deposit' => $d, 'receipt' => $r4]);
ok($c === 200 && (string) one('SELECT total FROM deposits WHERE id = :d', ['d' => $d]) === '750.00' && one('SELECT deposit_id FROM receipts WHERE id = :r', ['r' => $r4]) === null, 'deposit_remove_receipt: back to 750.00, the receipt undeposited');
$body = page($bea, '/deposits/new?bank_account=' . $fx['bank'])['body'];
ok(str_contains($body, 'id="deposit-receipt-' . $r4 . '"') && !str_contains($body, 'id="deposit-receipt-' . $r1 . '"') === false || str_contains($body, 'id="deposit-total-amount"'), 'the form lists the undeposited receipts with a live total');
$body = page($bea, '/deposits/new')['body'];
ok(str_contains($body, 'id="deposit-bank-form"') && str_contains($body, 'SMOKE Checking'), 'without a bank account the form asks for one first');
echo "2. Record\n";
$u0 = $bal('1050'); $b0 = $bal('1010');
$since = last_activity_id();
[$c, $b] = act($bea, '/deposits/record.php', ['deposit' => $d]);
ok($c === 200 && (string) one('SELECT status FROM deposits WHERE id = :d', ['d' => $d]) === 'recorded', 'deposit_record: recorded');
$je = (int) one('SELECT journal_entry_id FROM deposits WHERE id = :d', ['d' => $d]);
$jl = q('SELECT a.code, l.debit, l.credit FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e ORDER BY l.line_no', ['e' => $je]);
ok($jl[0]['code'] === '1010' && $jl[0]['debit'] === '750.00' && $jl[1]['code'] === '1050' && $jl[1]['credit'] === '750.00', 'the entry: DR 1010 750.00 / CR 1050 750.00');
ok(m_sub($bal('1050'), $u0) === '-750.00' && m_sub($bal('1010'), $b0) === '750.00', 'Undeposited funds fell by 750.00 and the bank rose by it');
$log = activity('deposit.record', $since)[0];
$a = json_decode((string) $log['after'], true);
ok((int) $log['journal_entry_id'] === $je && (int) $log['bank_account_id'] === $fx['bank'] && $a['amount'] === '750.00' && $a['currency'] === 'USD' && $a['receipts'] === 2, 'deposit.record: journal_entry_id, bank_account_id, amount, currency, receipts');
[$c, $b] = act($bea, '/deposits/remove.php', ['deposit' => $d, 'receipt' => $r1]);
ok($c === 422 && str_contains(msg($b), 'The deposit is recorded; a receipt leaves a draft deposit only'), 'a receipt cannot leave a recorded deposit');
[$c, $b] = act($bea, '/deposits/record.php', ['deposit' => $d]);
ok($c === 422 && str_contains(msg($b), 'is already recorded'), 'recording twice: 422');
[$c, $b] = act($bea, '/deposits/delete.php', ['deposit' => $d]);
ok($c === 422 && str_contains(msg($b), 'only a draft is deleted'), 'only a draft is deleted');
$body = page($bea, '/deposits/' . $d)['body'];
ok(str_contains($body, 'id="deposit-head-entry-link"') && str_contains($body, 'id="deposit-receipt-' . $r1 . '"') && str_contains($body, 'Not matched to a bank line yet.') && !str_contains($body, 'id="deposit-record-btn"'), 'the page: the entry, the receipts, "not matched yet" (slice 6 fills it), no Record');
$body = page($bea, '/receipts/' . $r1)['body'];
ok(str_contains($body, 'id="receipt-head-where"') && str_contains($body, 'DEP-'), 'the receipt says which deposit it is in');
echo "3. Void\n";
[$c, $b] = act($bea, '/deposits/void.php', ['deposit' => $d, 'reason' => 'x']);
ok($c === 403, 'a Bookkeeper may not void (journal.override)');
$since = last_activity_id();
[$c, $b] = act($carl, '/deposits/void.php', ['deposit' => $d, 'reason' => 'SMOKE wrong bank']);
ok($c === 200 && (string) one('SELECT status FROM deposits WHERE id = :d', ['d' => $d]) === 'void' && count(activity('deposit.void', $since)) === 1, 'the Controller voids it; deposit.void logged (' . $c . ' ' . msg($b) . ')');
ok(one('SELECT deposit_id FROM receipts WHERE id = :r', ['r' => $r1]) === null && one('SELECT deposit_id FROM receipts WHERE id = :r', ['r' => $r2]) === null, 'its receipts are undeposited again');
ok($bal('1050') === $u0 && $bal('1010') === $b0 && (int) one('SELECT count(*) FROM journal_entries WHERE reversal_of = :e', ['e' => $je]) === 1, 'the entry is reversed: both balances are back');
ok(in_array($r1, array_column(undeposited_probe(), 'receipt_id'), true), 'and the receipts can join another deposit');
echo "4. Delete a draft\n";
[$c, $b] = act($bea, '/deposits/save.php', ['bank_account' => $fx['bank'], 'receipts' => [$r1]]);
$d2 = (int) $b['record_id'];
$since = last_activity_id();
[$c, $b] = act($bea, '/deposits/delete.php', ['deposit' => $d2]);
ok($c === 200 && one('SELECT 1 FROM deposits WHERE id = :d', ['d' => $d2]) === false && one('SELECT deposit_id FROM receipts WHERE id = :r', ['r' => $r1]) === null && count(activity('deposit.delete', $since)) === 1, 'deposit_delete: the draft is gone, its receipt returns; deposit.delete logged');
[$c, $b] = act($bea, '/deposits/record.php', ['deposit' => (int) act($bea, '/deposits/save.php', ['bank_account' => $fx['bank']])[1]['record_id']]);
ok($c === 422 && str_contains(msg($b), 'has no receipts'), 'an empty deposit is not recorded: 422');
[$c, $d3] = screen($vera, '/deposits/');
ok($c === 200 && count($d3['deposits']) >= 1, 'the list (a Viewer reads it)');
$body = page($vera, '/deposits/')['body'];
ok(str_contains($body, 'id="deposit-card-' . $d . '"') && !str_contains($body, 'id="deposits-list-add-btn"') && str_contains($body, 'id="deposits-undeposited"'), 'cards, no New deposit button for a Viewer, the undeposited count');
ok(page($bea, '/deposits/424242')['code'] === 404, 'an unknown deposit: 404');
finish();
function undeposited_probe(): array { pdo()->exec("SELECT set_config('app.member_id', '1', false)"); return q("SELECT receipt_id FROM mcp_receipts WHERE status = 'recorded' AND deposit_to_bank_account_id IS NULL AND deposit_id IS NULL"); }
